"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3796],{23796:a=>{a.exports=JSON.parse('{"slug":"indeksaciya-pensiy-2027-fevral-aprel","locale":"zh","title":"2027年养老金将两次调整：二月6.8%，四月3.3%","description":"2027年保险养老金二月1日增6.8%，四月1日增3.3%。解释双重调整及实际增加额。","blocks":[{"id":"b001","kind":"paragraph","text":"社会基金主席谢尔盖\xb7奇尔科夫公布，2027年非在职老年保险养老金年均为30 241卢布，比2026年高2466卢布。调整分两阶段：二月1日加6.8%，四月1日再加3.3%，合计10.3%。涉及超过37百万领取保险养老金者，也包括在职退休人员；他们自2025年重新获得指数化调整。"},{"id":"b002","kind":"paragraph","text":"2026年仅在一月1日调整一次，幅度7.6%。二月与四月双阶段机制在2019年前法律中已存在，如今恢复。两阶段逻辑不同：二月补偿上一年通胀，6.8%暂为估计，Rosstat一月确定实际值；四月依据社会基金收入，若工资及缴费增长快于物价，基金才有超通胀加发空间。"},{"id":"b003","kind":"paragraph","text":"设想工资每年二月才按已发生的通胀上调。此前全年价格上涨，收入不变，到一月购买力已下降。二月只是恢复旧购买力，并不补偿全年损失，这就是追赶式指数化。调整日移到二月1日意味着2027年一月，退休人员仍以旧养老金承受新年价格。"},{"id":"b004","kind":"paragraph","text":"这解释了数字差异：若养老金涨10.3%，为何平均只多2466卢布、约9%？因为30 241卢布是2027全年平均。一月旧标准，二三月一次调整，四月后才计两次。按本文计算，四月起非在职平均约30.6千卢布，比2026年约高10%。"},{"id":"b005","kind":"paragraph","text":"真实增幅取决于通胀。若2026年物价上涨6.8%，二月只补偿，四月3.3%才超出上一年通胀。但2027年物价还会涨，又会吞掉部分增加。央行调查分析师预计2026年末7.1%；二月按实际通胀调，因此若高于估计，增幅也会更大。社会养老金另从四月1日按最低生活标准增长调整，暂估6.8%。"},{"id":"b006","kind":"paragraph","text":"在职退休人员还将在2027年八月1日起根据雇主2026年缴费重新计算，但最多增加3个养老金积分。每人卢布增额依养老金而异，可在社会基金个人账户查看。2027年基金预算草案仍需杜马通过；四月增加额已预先计入，假设工资与缴费继续快于物价。"},{"id":"b007","kind":"heading","text":"2027年养老金调整多少？"},{"id":"b008","kind":"paragraph","text":"保险养老金二月1日提高6.8%，这是2026年通胀估计；四月1日再加3.3%，合计10.3%。每人的卢布增加额取决于原养老金。"},{"id":"b009","kind":"heading","text":"在职退休者也调整吗？"},{"id":"b010","kind":"paragraph","text":"是的，自2025年保险养老金也为在职者调整，2027年两次均适用。此外八月1日按雇主缴费重算，但最多3个养老金积分。"},{"id":"b011","kind":"heading","text":"为何平均只增加2466卢布，而不是10%？"},{"id":"b012","kind":"paragraph","text":"30 241卢布是2027全年平均。一月旧金额，二三月一次调整，四月起才含两次。四月后非在职平均约30.6千卢布，比2026年高约10%。"}],"sources":[{"label":"2027年老年保险养老金平均金额将提高","url":"https://www.kommersant.ru/doc/9042520"},{"label":"2027年保险养老金将两次调整","url":"https://mintrud.gov.ru/pensions/94"},{"label":"2027年养老金将在二月和四月调整","url":"https://www.interfax.ru/russia/1119578"},{"label":"2027年保险养老金增幅将快于通胀","url":"https://aif.ru/society/strahovye-pensii-v-2027-godu-budut-rasti-bystree-inflyacii"},{"label":"2027年养老金：双重调整、时间表与新金额","url":"https://news.ru/economics/pensii-v-2027-godu-dvojnaya-indeksaciya-grafik-povyshenij-i-novye-summy"},{"label":"俄罗斯央行2026年十月宏观调查","url":"https://www.cbr.ru/content/document/file/193892/survey_pdf.pdf"},{"label":"2026年养老金指数化调整","url":"https://www.banki.ru/webview/dialog/articles/40554/"},{"label":"公布俄罗斯2027年养老金增加额","url":"https://lenta.ru/news/2026/10/20/raskryta-summa-uvelicheniya-pensiy-v-rossii-v-2026-godu"},{"label":"公布2027年平均保险养老金","url":"https://lenta.ru/news/2026/10/21/rossiyanam-nazvali-sredniy-razmer-strahovoy-pensii-v-2027-godu"}],"sourceBodySha256":"dbab3190117599a76dceb4c08cb97459487f6cc30b90ee5c5a928314ad375a22"}')}}]);